changeSet.sql:
CREATE TABLE announcement ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, title VARCHAR(200) NOT NULL, message TEXT NOT NULL, audience_type VARCHAR(20) NOT NULL, academic_year_id BIGINT REFERENCES academic_year(id), grade_id BIGINT REFERENCES grade(id), section_id BIGINT REFERENCES section(id), priority VARCHAR(20) NOT NULL DEFAULT 'NORMAL', status VARCHAR(20) NOT NULL DEFAULT 'DRAFT', created_by BIGINT NOT NULL REFERENCES "user"(id), scheduled_at TIMESTAMP, expires_at TIMESTAMP, published_at TIMESTAMP, archived_at TIMESTAMP, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT chk_announcement_audience CHECK (audience_type IN ('ALL','STUDENTS','FACULTY','CLASS')), CONSTRAINT chk_announcement_priority CHECK (priority IN ('NORMAL','IMPORTANT','URGENT')), CONSTRAINT chk_announcement_status CHECK (status IN ('DRAFT','SCHEDULED','PUBLISHED','ARCHIVED')), CONSTRAINT chk_announcement_class_target CHECK ( (audience_type = 'CLASS' AND academic_year_id IS NOT NULL AND grade_id IS NOT NULL AND section_id IS NOT NULL) OR (audience_type <> 'CLASS' AND section_id IS NULL) ) ); CREATE INDEX idx_announcement_status_schedule ON announcement(status, scheduled_at); CREATE INDEX idx_announcement_created_by ON announcement(created_by, created_at DESC);
CREATE TABLE announcement_recipient ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, announcement_id BIGINT NOT NULL REFERENCES announcement(id) ON DELETE CASCADE, user_id BIGINT NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, read_at TIMESTAMP, delivered_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT uk_announcement_recipient UNIQUE (announcement_id, user_id) ); CREATE INDEX idx_announcement_recipient_user ON announcement_recipient(user_id, read_at);
CREATE TABLE notification ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, source_type VARCHAR(20) NOT NULL, source_id BIGINT, title VARCHAR(200) NOT NULL, message VARCHAR(1000) NOT NULL, category VARCHAR(30) NOT NULL, priority VARCHAR(20) NOT NULL DEFAULT 'NORMAL', target_url VARCHAR(500), deduplication_key VARCHAR(180), read_at TIMESTAMP, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT chk_notification_source CHECK (source_type IN ('SYSTEM','ANNOUNCEMENT','MANUAL')), CONSTRAINT chk_notification_priority CHECK (priority IN ('NORMAL','IMPORTANT','URGENT')), CONSTRAINT uk_notification_deduplication UNIQUE (deduplication_key) ); CREATE INDEX idx_notification_user_created ON notification(user_id, created_at DESC); CREATE INDEX idx_notification_user_unread ON notification(user_id, read_at, created_at DESC);
